    57→public class InputSourceSampler
    58→{
    59→  private static final String SAMPLER_DATA_SOURCE = "sampler";
    60→
    61→  private static final DataSchema DEFAULT_DATA_SCHEMA = new DataSchema(
    62→      SAMPLER_DATA_SOURCE,
    63→      new TimestampSpec(null, null, null),
    64→      new DimensionsSpec(null),
    65→      null,
    66→      null,
    67→      null
    68→  );
    69→
    70→  // We want to be able to sort the list of processed results back into the same order that we read them from the
    71→  // firehose so that the rows in the data loader are not always changing. To do this, we add a temporary column to the
    72→  // InputRow (in SamplerInputRow) and tag each row with a sortKey. We use an aggregator so that it will not affect
    73→  // rollup, and we use a longMin aggregator so that as rows get rolled up, the earlier rows stay stable and later
    74→  // rows may get rolled into these rows. After getting the results back from the IncrementalIndex, we sort by this
    75→  // column and then exclude it from the response.
    76→  private static final AggregatorFactory INTERNAL_ORDERING_AGGREGATOR = new LongMinAggregatorFactory(
    77→      SamplerInputRow.SAMPLER_ORDERING_COLUMN,
    78→      SamplerInputRow.SAMPLER_ORDERING_COLUMN
    79→  );
    80→
    81→  public SamplerResponse sample(
    82→      final InputSource inputSource,
    83→      // inputFormat can be null only if inputSource.needsFormat() = false or parser is specified.
    84→      @Nullable final InputFormat inputFormat,
    85→      @Nullable final DataSchema dataSchema,
    86→      @Nullable final SamplerConfig samplerConfig
    87→  )
    88→  {
    89→    Preconditions.checkNotNull(inputSource, "inputSource required");
    90→    if (inputSource.needsFormat()) {
    91→      Preconditions.checkNotNull(inputFormat, "inputFormat required");
    92→    }
    93→    final DataSchema nonNullDataSchema = dataSchema == null
    94→                                         ? DEFAULT_DATA_SCHEMA
    95→                                         : dataSchema;
    96→    final SamplerConfig nonNullSamplerConfig = samplerConfig == null
    97→                                               ? SamplerConfig.empty()
    98→                                               : samplerConfig;
    99→
   100→    final Closer closer = Closer.create();
   101→    final File tempDir = FileUtils.createTempDir();
   102→    closer.register(() -> FileUtils.deleteDirectory(tempDir));
   103→
   104→    final InputSourceReader reader = buildReader(
   105→        nonNullSamplerConfig,
   106→        nonNullDataSchema,
   107→        inputSource,
   108→        inputFormat,
   109→        tempDir
   110→    );
   111→    try (final CloseableIterator<InputRowListPlusRawValues> iterator = reader.sample();
   112→         final IncrementalIndex<Aggregator> index = buildIncrementalIndex(nonNullSamplerConfig, nonNullDataSchema);
   113→         final Closer closer1 = closer) {
   114→      SamplerResponseRow[] responseRows = new SamplerResponseRow[nonNullSamplerConfig.getNumRows()];
   115→      int counter = 0, numRowsIndexed = 0;
   116→
   117→      while (counter < responseRows.length && iterator.hasNext()) {
   118→        Map<String, Object> rawColumns = null;
   119→        try {
   120→          final InputRowListPlusRawValues inputRowListPlusRawValues = iterator.next();
   121→
   122→          if (inputRowListPlusRawValues.getRawValues() != null) {
   123→            rawColumns = inputRowListPlusRawValues.getRawValues();
   124→          }
   125→
   126→          if (inputRowListPlusRawValues.getParseException() != null) {
   127→            throw inputRowListPlusRawValues.getParseException();
   128→          }
   129→
   130→          if (inputRowListPlusRawValues.getInputRows() == null) {
   131→            continue;
   132→          }
   133→
   134→          for (InputRow row : inputRowListPlusRawValues.getInputRows()) {
   135→            index.add(new SamplerInputRow(row, counter), true);
   136→            // store the raw value; will be merged with the data from the IncrementalIndex later
   137→            responseRows[counter] = new SamplerResponseRow(rawColumns, null, null, null);
   138→            counter++;
   139→            numRowsIndexed++;
   140→          }
   141→        }
   142→        catch (ParseException e) {
   143→          responseRows[counter] = new SamplerResponseRow(rawColumns, null, true, e.getMessage());
   144→          counter++;
   145→        }
   146→      }
   147→
   148→      final List<String> columnNames = index.getColumnNames();
   149→      columnNames.remove(SamplerInputRow.SAMPLER_ORDERING_COLUMN);
   150→
   151→      for (Row row : index) {
   152→        Map<String, Object> parsed = new HashMap<>();
   153→
   154→        columnNames.forEach(k -> parsed.put(k, row.getRaw(k)));
   155→        parsed.put(ColumnHolder.TIME_COLUMN_NAME, row.getTimestampFromEpoch());
   156→
   157→        Number sortKey = row.getMetric(SamplerInputRow.SAMPLER_ORDERING_COLUMN);
   158→        if (sortKey != null) {
   159→          responseRows[sortKey.intValue()] = responseRows[sortKey.intValue()].withParsed(parsed);
   160→        }
   161→      }
   162→
   163→      return new SamplerResponse(
   164→          counter,
   165→          numRowsIndexed,
   166→          Arrays.stream(responseRows)
   167→                .filter(Objects::nonNull)
   168→                .filter(x -> x.getParsed() != null || x.isUnparseable() != null)
   169→                .collect(Collectors.toList())
   170→      );
   171→    }
   172→    catch (Exception e) {
   173→      throw new SamplerException(e, "Failed to sample data: %s", e.getMessage());
   174→    }
   175→  }
   176→
   177→  private InputSourceReader buildReader(
   178→      SamplerConfig samplerConfig,
   179→      DataSchema dataSchema,
   180→      InputSource inputSource,
   181→      @Nullable InputFormat inputFormat,
   182→      File tempDir
   183→  )
   184→  {
   185→    final List<String> metricsNames = Arrays.stream(dataSchema.getAggregators())
   186→                                            .map(AggregatorFactory::getName)
   187→                                            .collect(Collectors.toList());
   188→    final InputRowSchema inputRowSchema = new InputRowSchema(
   189→        dataSchema.getTimestampSpec(),
   190→        dataSchema.getDimensionsSpec(),
   191→        metricsNames
   192→    );
   193→
   194→    InputSourceReader reader = inputSource.reader(inputRowSchema, inputFormat, tempDir);
   195→
   196→    if (samplerConfig.getTimeoutMs() > 0) {
   197→      reader = new TimedShutoffInputSourceReader(reader, DateTimes.nowUtc().plusMillis(samplerConfig.getTimeoutMs()));
   198→    }
   199→
   200→    return dataSchema.getTransformSpec().decorate(reader);
   201→  }
   202→
   203→  private IncrementalIndex<Aggregator> buildIncrementalIndex(SamplerConfig samplerConfig, DataSchema dataSchema)
   204→  {
   205→    final IncrementalIndexSchema schema = new IncrementalIndexSchema.Builder()
   206→        .withTimestampSpec(dataSchema.getTimestampSpec())
   207→        .withQueryGranularity(dataSchema.getGranularitySpec().getQueryGranularity())
   208→        .withDimensionsSpec(dataSchema.getDimensionsSpec())
   209→        .withMetrics(ArrayUtils.addAll(dataSchema.getAggregators(), INTERNAL_ORDERING_AGGREGATOR))
   210→        .withRollup(dataSchema.getGranularitySpec().isRollup())
   211→        .build();
   212→
   213→    return new IncrementalIndex.Builder().setIndexSchema(schema)
   214→                                         .setMaxRowCount(samplerConfig.getNumRows())
   215→                                         .buildOnheap();
   216→  }
   217→}
