    84→  @JsonProperty
    85→  @Nullable
    86→  public DimFilter getFilter()
    87→  {
    88→    return filter;
    89→  }
    90→
    91→  @JsonProperty
    92→  public List<Transform> getTransforms()
    93→  {
    94→    return transforms;
    95→  }
    96→
    97→  public <T> InputRowParser<T> decorate(final InputRowParser<T> parser)
    98→  {
    99→    // Always decorates, even if the transformSpec is a no-op. This is so fromInputRowParser can insist that the
   100→    // parser is a transforming parser, and possibly help detect coding errors where someone forgot to call "decorate".
   101→
   102→    if (parser instanceof StringInputRowParser) {
   103→      // Hack to support the fact that some callers use special methods in StringInputRowParser, such as
   104→      // parse(String) and startFileFromBeginning.
   105→      return (InputRowParser<T>) new TransformingStringInputRowParser(
   106→          parser.getParseSpec(),
   107→          ((StringInputRowParser) parser).getEncoding(),
   108→          this
   109→      );
   110→    } else {
   111→      return new TransformingInputRowParser<>(parser, this);
   112→    }
   113→  }
   114→
   115→  public InputSourceReader decorate(InputSourceReader reader)
   116→  {
   117→    return new TransformingInputSourceReader(reader, toTransformer());
   118→  }
