    81→      @Deprecated @JsonProperty("parser") @Nullable Map<String, Object> parserMap,
    82→      @JacksonInject ObjectMapper objectMapper
    83→  )
    84→  {
    85→    validateDatasourceName(dataSource);
    86→    this.dataSource = dataSource;
